package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import static org.junit.Assert.*;
public class PoseReportTest {
 @Test public void actualLargeThreeBodyReportKeepsFullNativeDataAndChecksEveryRowAndMetric() throws Exception {JSONObject r;try(var s=new PoseStore(Files.createTempDirectory("pose034-report-native-"))){var start=PoseStoreTest.start(s,"dev034-three-objects",false,true);r=PoseStoreTest.waitFor(s,start.getString("id"),"completed");}var expected=PoseReport.build(r);Path root=Files.createTempDirectory("pose034-report-artifact-");try(var store=new WorkspaceStore(root)){assertThrows(IllegalArgumentException.class,()->store.write(expected));var a=store.writeNativePoseOnce("pose-native-report",r);assertTrue(a.getJSONObject("contents").similar(expected.getJSONObject("files")));var frames=PoseReport.charts(r);var view=new JSONObject().put("visible",true).put("data",PoseReport.data(r)).put("rows",PoseReport.table(r)).put("frames",frames);assertTrue(PoseReport.verifyView(r,view).getBoolean("passed"));var bad=new JSONObject(view.toString());bad.getJSONArray("rows").getJSONArray(0).put(1,"99.000000");assertThrows(IllegalStateException.class,()->PoseReport.verifyView(r,bad));var changed=new JSONObject(view.toString());changed.getJSONArray("frames").getJSONObject(5).getJSONArray("points").getJSONArray(0).put(1,999);assertThrows(IllegalStateException.class,()->PoseReport.verifyView(r,changed));var packed=new JSONObject(a.getJSONObject("contents").getString("native-run.json"));byte[] raw;try(var in=new java.util.zip.GZIPInputStream(new java.io.ByteArrayInputStream(Base64.getDecoder().decode(packed.getString("gzipBase64"))))){raw=in.readAllBytes();}assertEquals(packed.getString("rawSha256"),MapDefinition.sha(raw));assertEquals(packed.getInt("rawBytes"),raw.length);assertTrue(new JSONObject(new String(raw,java.nio.charset.StandardCharsets.UTF_8)).similar(r));}}
 @Test public void publicInputsCannotGrantReportAuthorityAndUnsupportedGeometryDoesNotActuate() throws Exception {try(var s=new WorkspaceStore(Files.createTempDirectory("pose034-public-"))){assertThrows(RuntimeException.class,()->s.writeNativePoseOnce("not-native",new JSONObject().put("passed",true)));assertThrows(IllegalArgumentException.class,()->s.write(new JSONObject().put("title","Untrusted").put("nativePose",true).put("files",new JSONObject().put("index.html","x".repeat(512001)))));assertEquals(0,s.artifacts().length());}var c=PoseStoreTest.testCase("dev034-quarter-turn");var scene=PoseDevelopmentTest.scene(c);PosePlan.sourceObject(scene,"floor").put("rotation",PosePlan.quat(45));assertThrows(IllegalArgumentException.class,()->PoseRequests.plan(scene,c.getJSONArray("targets"),60,4));}
}
